$tpages=static function(?array $list,string $key)use($tt,$tv,$th,$tu):void{$raw=$list['page_input']??$_GET[$key]??'1'; ?><form method="get" class="general-settings-page-form"><?= $th([$key]) ?><label class="general-settings-field"><?= e($tt('Seite')) ?><input class="form-control" name="<?= e($key) ?>" value="<?= e($tv($raw)) ?>" inputmode="numeric"></label><button class="btn btn-outline theme-secondary"><?= e($tt('Seite öffnen')) ?></button><?php if($list): ?><span><?= e($list['total']) ?> · <?= e($list['pages']) ?></span><?php if(($list['page']??null)>1): ?><a class="btn btn-outline theme-secondary" href="<?= e($tu([$key=>(string)($list['page']-1)])) ?>"><?= e($tt('Zurück')) ?></a><?php endif;if(($list['page']??null)!==null&&$list['page']<$list['pages']): ?><a class="btn btn-outline theme-secondary" href="<?= e($tu([$key=>(string)($list['page']+1)])) ?>"><?= e($tt('Weiter')) ?></a><?php endif;endif ?></form><?php };
$tselect=static function(string $key,array $choices,mixed $value)use($tt,$tv):void{$raw=$tv($value); ?><select class="form-control" name="data[<?= e($key) ?>]"><?php if(!array_key_exists($raw,$choices)): ?><option value="<?= e($raw) ?>" selected><?= e($raw) ?></option><?php endif;foreach($choices as$option=>$label): ?><option value="<?= e($option) ?>"<?= (string)$option===$raw?' selected':'' ?>><?= e($tt($label)) ?></option><?php endforeach ?></select><?php };
